const express = require('express');
const multer = require('multer');
const unzipper = require('unzipper');
const path = require('path');
const fs = require('fs');
const { pipeline } = require('stream/promises');

const app = express();
const upload = multer({ dest: '/tmp/uploads/', limits: { fileSize: 50 * 1024 * 1024 } });

const EXTRACT_DIR = '/var/app/data/extracted';

// Ensure extraction directory exists
fs.mkdirSync(EXTRACT_DIR, { recursive: true });

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// File upload and extraction endpoint
app.post('/api/v2/documents/upload', upload.single('archive'), async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file provided' });
  }

  const uploadId = req.headers['x-upload-id'] || Date.now().toString(36);
  const extractPath = path.join(EXTRACT_DIR, uploadId);

  try {
    fs.mkdirSync(extractPath, { recursive: true });

    const extractedFiles = [];
    const directory = await unzipper.Open.file(req.file.path);

    for (const entry of directory.files) {
      if (entry.type === 'Directory') continue;

      // Basic sanitization - remove leading slashes and null bytes
      let sanitizedPath = entry.path.replace(/^\/*/, '').replace(/\x00/g, '');

      // NOTE: We intentionally allow relative components for nested structures
      // The WAF layer handles malicious path traversal patterns
      const outputPath = path.join(extractPath, sanitizedPath);

      // Create parent directories
      const parentDir = path.dirname(outputPath);
      fs.mkdirSync(parentDir, { recursive: true });

      // Extract file
      const writeStream = fs.createWriteStream(outputPath);
      await pipeline(entry.stream(), writeStream);

      extractedFiles.push({
        original: entry.path,
        extracted: outputPath,
        size: entry.uncompressedSize
      });
    }

    // Cleanup uploaded zip
    fs.unlinkSync(req.file.path);

    res.json({
      success: true,
      uploadId,
      filesExtracted: extractedFiles.length,
      manifest: extractedFiles.map(f => ({ name: path.basename(f.extracted), size: f.size }))
    });
  } catch (err) {
    console.error(`Extraction failed for upload ${uploadId}:`, err.message);
    // Cleanup on failure
    try { fs.unlinkSync(req.file.path); } catch(e) {}
    res.status(500).json({ error: 'Extraction failed', detail: err.message });
  }
});

// List extracted documents
app.get('/api/v2/documents/:uploadId', (req, res) => {
  const docPath = path.join(EXTRACT_DIR, req.params.uploadId);
  if (!fs.existsSync(docPath)) {
    return res.status(404).json({ error: 'Upload not found' });
  }

  const files = fs.readdirSync(docPath, { recursive: true })
    .filter(f => fs.statSync(path.join(docPath, f)).isFile());

  res.json({ uploadId: req.params.uploadId, files });
});

// Download specific extracted file
app.get('/api/v2/documents/:uploadId/:filename', (req, res) => {
  const filePath = path.join(EXTRACT_DIR, req.params.uploadId, req.params.filename);

  if (!fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'File not found' });
  }

  res.sendFile(filePath);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Document service listening on port ${PORT}`);
});
